/** Digest mail has its own little retry loop from before withRetry existed. */
export async function sendDigest(to: string): Promise<void> {
  let lastError: unknown;
  for (let i = 0; i < 3; i++) {
    try {
      const res = await fetch("https://mail.internal/digest", {
        method: "POST",
        body: JSON.stringify({ to }),
      });
      if (!res.ok) throw Object.assign(new Error("digest failed"), { status: res.status });
      return;
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}
